PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY, student_id TEXT UNIQUE NOT NULL, password TEXT NOT NULL, nickname TEXT NOT NULL, college TEXT NOT NULL, class_name TEXT NOT NULL DEFAULT '', contact TEXT NOT NULL DEFAULT '', email TEXT NOT NULL DEFAULT '', role TEXT NOT NULL DEFAULT 'student', credit INTEGER NOT NULL DEFAULT 100, cancellations INTEGER NOT NULL DEFAULT 0, auth_version INTEGER NOT NULL DEFAULT 0, sso_id TEXT, deleted_at TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS courses (code TEXT PRIMARY KEY, name TEXT NOT NULL, college TEXT NOT NULL, textbook TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS uploads (url TEXT PRIMARY KEY, owner_id INTEGER NOT NULL REFERENCES users(id));
CREATE TABLE IF NOT EXISTS books (id INTEGER PRIMARY KEY, owner_id INTEGER NOT NULL REFERENCES users(id), course_code TEXT NOT NULL REFERENCES courses(code), title TEXT NOT NULL, edition TEXT NOT NULL DEFAULT '', isbn TEXT NOT NULL DEFAULT '', condition INTEGER NOT NULL CHECK(condition BETWEEN 1 AND 5), price INTEGER NOT NULL CHECK(price>=0), notes TEXT NOT NULL DEFAULT '', images TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending', review_reason TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS reservations (id INTEGER PRIMARY KEY, book_id INTEGER NOT NULL REFERENCES books(id), buyer_id INTEGER NOT NULL REFERENCES users(id), meeting_time TEXT NOT NULL, place TEXT NOT NULL, message TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'pending', seller_confirm INTEGER NOT NULL DEFAULT 0, buyer_confirm INTEGER NOT NULL DEFAULT 0, reason TEXT NOT NULL DEFAULT '', updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX IF NOT EXISTS one_active_reservation ON reservations(book_id) WHERE status IN ('pending','accepted','ready','confirming','disputed');
CREATE TABLE IF NOT EXISTS ratings (id INTEGER PRIMARY KEY, reservation_id INTEGER NOT NULL REFERENCES reservations(id), author_id INTEGER NOT NULL REFERENCES users(id), target_id INTEGER NOT NULL REFERENCES users(id), punctuality INTEGER NOT NULL, accuracy INTEGER NOT NULL, communication INTEGER NOT NULL, tags TEXT NOT NULL DEFAULT '', comment TEXT NOT NULL DEFAULT '', deleted INTEGER NOT NULL DEFAULT 0, UNIQUE(reservation_id,author_id));
CREATE TABLE IF NOT EXISTS reports (id INTEGER PRIMARY KEY, author_id INTEGER NOT NULL REFERENCES users(id), book_id INTEGER NOT NULL REFERENCES books(id), reason TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending', resolution TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS notifications (id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id), message TEXT NOT NULL, seen INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS logs (id INTEGER PRIMARY KEY, actor_id INTEGER REFERENCES users(id), action TEXT NOT NULL, entity TEXT NOT NULL, entity_id TEXT NOT NULL, detail TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS settings (key TEXT PRIMARY KEY, value INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS login_attempts (identity TEXT PRIMARY KEY, failures INTEGER NOT NULL DEFAULT 0, last_attempt REAL NOT NULL);
CREATE INDEX IF NOT EXISTS book_search ON books(status,course_code,price);
CREATE INDEX IF NOT EXISTS buyer_reservations ON reservations(buyer_id);
CREATE TABLE IF NOT EXISTS report_appeals (appeal_id INTEGER PRIMARY KEY REFERENCES reports(id), original_id INTEGER UNIQUE NOT NULL REFERENCES reports(id));
CREATE TABLE IF NOT EXISTS report_penalties (report_id INTEGER PRIMARY KEY REFERENCES reports(id), amount INTEGER NOT NULL, reversed INTEGER NOT NULL DEFAULT 0);
CREATE UNIQUE INDEX IF NOT EXISTS unique_user_email ON users(email) WHERE email <> '';
CREATE TABLE IF NOT EXISTS email_codes (id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id), email TEXT NOT NULL, code_hash TEXT NOT NULL, expires_at TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS password_resets (id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id), token_hash TEXT NOT NULL UNIQUE, expires_at TEXT NOT NULL, used_at TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
